'use strict';
let organiserKey='',organiserResults=null,organiserError='';
function sharingPanel(){const s=Learning.status();return `<section class="sharing-panel"><div>${icon('shield')}<strong>Your learning, your choice.</strong></div><p>Quiz answers, retries and scores can be shared under a random learner ID. Your name, personal plan notes, support choices and booking details are never included.</p>${s.online?`<label class="check-row"><input id="share-results" type="checkbox" ${s.consent?'checked':''}><span>Share my anonymous quiz results with the organiser</span></label><p class="body-note">Only answers submitted after you switch this on are shared. You can change this in “Your data”.</p>`:'<p class="body-note">Local mode: your quiz history stays on this device. Open the server version to share results with an organiser.</p>'}</section>`}
function reviewPage(path){
 const qs=Curriculum.questions(path),draft=Learning.draft(path),round=(Learning.rounds(path).at(-1)||0)+1;
 return `<div class="page review-page"><a class="back-link" href="${Learning.rounds(path).length?'#complete/'+path:'#learn/'+path+'/'+(CHAPTERS[path].length-1)}">← Back</a><div class="eyebrow">PUT IT ALL TOGETHER</div><h1>One last practice.</h1><p class="page-intro">Try the same questions again, including your emergency kit. Submit all your answers to see what has changed since your first try. There is no time limit.</p><p class="body-note"><span>Final check</span> <bdi>${round}</bdi> · <span>Choose one answer unless the question says to select all.</span></p><form id="review-form">${qs.map((q,i)=>`<fieldset class="review-question"><legend><span class="review-number">${i+1}</span><span>${q.title}</span></legend>${q.multiple?'<p>Select all that belong in the bag.</p>':''}<div class="review-options">${q.options.map(o=>`<label class="review-option"><input type="${q.multiple?'checkbox':'radio'}" name="review-${q.id}" value="${o.id}" data-review="${q.id}" ${draft[q.id]?.includes(o.id)?'checked':''} ${q.multiple?'':'required'}><span>${o.label}</span></label>`).join('')}</div></fieldset>`).join('')}<p id="review-error" class="form-error" role="alert"></p><button class="primary" type="submit">See my results ${icon('arrow')}</button></form></div>`;
}
function answerLabel(q,e){return e?e.selected.length?e.selected.map(id=>q.options.find(o=>o.id===id)?.label||id).map(s=>`<span>${esc(s)}</span>`).join(' · '):'<span>No items selected</span>':'<span>Not recorded</span>'}
function learningSummary(path){
 const first=Learning.score(path,'practice'),round=Learning.rounds(path).at(-1),last=Learning.score(path,'final',round);
 const paired=first.items.filter(x=>x.e),before=paired.filter(x=>Curriculum.correct(x.q,x.e.selected)).length,after=paired.filter(x=>{const e=last.items.find(y=>y.q.id===x.q.id)?.e;return e&&Curriculum.correct(x.q,e.selected)}).length;
 const change=paired.length?Math.round((after-before)/paired.length*100):null;
 return `<section class="learning-results"><div class="panel-heading"><div><div class="mini-label">YOUR LEARNING SNAPSHOT</div><h2>See how far you have come.</h2></div>${icon('spark')}</div><div class="score-grid"><div><span>First tries</span><strong><bdi>${first.correct} / ${first.recorded}</bdi></strong><small>Recorded practice questions</small></div><div><span>Latest final check</span><strong><bdi>${last.correct} / ${last.total}</bdi></strong><small><span>Final check</span> <bdi>${round||1}</bdi></small></div><div><span>Change</span><strong><bdi>${change===null?'—':(change>0?'+':'')+change}</bdi>${change===null?'':'<small>percentage points</small>'}</strong><small>Same recorded questions only</small></div></div>${first.recorded<first.total?'<p class="notice">Some first answers were not recorded. The comparison uses only questions with a recorded first attempt. Start this path again for a complete comparison.</p>':''}<p>Every try is useful. Review the safer choices below, then take your questions to the building walk.</p><div class="results-questions">${last.items.map(({q,e})=>{const f=Learning.first(path,q.id),ok=e&&Curriculum.correct(q,e.selected);return `<details><summary><span class="result-mark ${ok?'good':'retry'}">${ok?'✓':'↻'}</span><span>${q.title}</span><span class="result-state">${ok?'Correct':'Review this'}</span></summary><dl><dt>First answer</dt><dd>${answerLabel(q,f)}</dd><dt>Final answer</dt><dd>${answerLabel(q,e)}</dd><dt>Safer choice</dt><dd>${answerLabel(q,{selected:q.answers})}</dd></dl><p>${q.feedback}</p></details>`}).join('')}</div><a class="secondary" href="#review/${path}">Try the final check again ↻</a></section>`;
}
function trackingPrivacy(){const s=Learning.status();return `${sharingPanel()}<p><span>Anonymous learner ID</span>: <bdi class="anonymous-id" translate="no">${esc(s.learner)}</bdi></p><p>${!s.storageOK?'Browser storage is unavailable. This quiz history may be lost when you close the page.':!s.consent?'Sharing is off.':s.error?'Results are waiting to upload. Check your connection and try again.':s.pending?'Some results are waiting to upload.':'Your shared answers are up to date.'}</p>${s.online?'<div class="actions"><button class="secondary" data-action="sync-results">Retry upload</button><button class="text-button" data-action="delete-results">Delete my shared quiz results</button></div>':''}<p id="tracking-status" role="status"></p>`}
function organiserPage(){
 if(!organiserResults)return `<div class="page narrow-page"><div class="eyebrow">FOR THE ORGANISER</div><h1>Anonymous learning results.</h1><p>See original answers, retries and final checks from learners who chose to share.</p><form id="organiser-form" class="white-panel"><label class="field"><span>Organiser key</span><input name="key" type="password" autocomplete="off" required></label><p>Use the organiser key from your hosting settings, or .data/admin-key.txt when running locally. Keep it private.</p><button class="primary" type="submit">Open results</button><p class="form-error" role="alert">${organiserError}</p></form></div>`;
 const runs=organiserResults.runs,paired=runs.filter(r=>r.first.recorded===r.first.total&&r.finals.some(f=>f.round===1));
 const avg=values=>values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length):null;
 const before=avg(paired.map(r=>r.first.correct/r.first.total*100)),after=avg(paired.map(r=>r.finals.find(f=>f.round===1).correct/r.first.total*100));
 return `<div class="page organiser-page"><div class="eyebrow">FOR THE ORGANISER</div><h1>What is making a difference?</h1><div class="actions"><button class="secondary" data-action="refresh-results">Refresh results</button><button class="primary" data-action="export-results">Export answer history (CSV)</button><button class="text-button" data-action="lock-results">Lock results</button></div><p class="form-error" role="alert">${organiserError}</p><div class="score-grid"><div><span>Learning runs</span><strong>${runs.length}</strong><small><span>Anonymous learners</span>: ${new Set(runs.map(r=>r.learnerId)).size}</small></div><div><span>First tries</span><strong>${before===null?'—':before+'%'}</strong><small>Complete paired runs only</small></div><div><span>First final check</span><strong>${after===null?'—':after+'%'}</strong><small><span>Complete paired runs</span>: ${paired.length}</small></div></div><p>Each restart is a new run. The comparison uses the first final check, so later retakes do not overwrite it. Incomplete baselines are excluded from the averages.</p>${!runs.length?'<div class="notice">No shared answers yet. Learners must open the server version and switch on anonymous sharing before answering.</div>':runs.map(r=>`<details class="organiser-run"><summary><span>${r.path==='access'?'Your supported plan':'Resident & renter path'}</span><bdi class="anonymous-id" translate="no">${esc(r.learnerId.slice(0,8))} · ${esc(r.id.slice(0,8))}</bdi><span><span>First tries</span>: ${r.first.correct}/${r.first.recorded}</span><span><span>First final check</span>: ${r.finals.find(f=>f.round===1)?.correct??'—'}/${r.first.total}</span><span><span>Final checks</span>: ${r.finals.length}</span></summary><p><span>Anonymous learner ID</span>: <bdi translate="no">${esc(r.learnerId)}</bdi></p><p><span>Run ID</span>: <bdi translate="no">${esc(r.id)}</bdi></p><div class="results-table-scroll"><table><caption>Every submitted answer, in order</caption><thead><tr><th>#</th><th>Stage</th><th>Question</th><th>Selected answer</th><th>Result</th></tr></thead><tbody>${r.events.map(e=>{const q=Curriculum.questions(r.path).find(q=>q.id===e.question);return `<tr><td>${e.seq}</td><td><span>${e.stage==='practice'?'Practice':'Final check'}</span>${e.round?' '+e.round:''}</td><td>${esc(q.title)}</td><td>${answerLabel(q,e)}</td><td>${e.correct?'Correct':'Incorrect'}</td></tr>`}).join('')}</tbody></table></div></details>`).join('')}</div>`;
}
async function loadResults(){
 try{const r=await fetch('/api/results',{headers:{Authorization:'Bearer '+organiserKey},signal:AbortSignal.timeout(10000)});if(!r.ok)throw new Error();organiserResults=await r.json();organiserError=''}catch{organiserError='Results could not be opened. Check the server and organiser key.'}
 if(current.view==='organiser')render(false);
}
function exportResults(){
 if(!organiserResults)return;
 const rows=[['learner_id','run_id','path','sequence','stage','final_round','attempt_number','question_id','question','selected_ids','selected_answers','correct','client_time','received_time']];
 for(const r of organiserResults.runs)for(const e of r.events){const q=Curriculum.questions(r.path).find(q=>q.id===e.question);rows.push([r.learnerId,r.id,r.path,e.seq,e.stage,e.round,e.attempt,e.question,q.title,e.selected.join(';'),e.selected.map(id=>q.options.find(o=>o.id===id)?.label||id).join('; '),e.correct,e.at,e.receivedAt])}
 const cell=value=>{let text=String(value??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'};
 download('Southbank-anonymous-answers.csv','\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');
}
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.id==='share-results'){Learning.consent(el.checked);announce(el.checked?'Anonymous sharing is on for future answers.':'Sharing is off.');}
 if(el.id==='poster-notes'){posterIncludeNotes=el.checked;render(false);document.getElementById('poster-notes').focus()}
 if(el.dataset.review){const q=Curriculum.questions(current.path).find(q=>q.id===el.dataset.review);if(!q)return;const selected=q.multiple?Array.from(document.querySelectorAll(`[data-review="${q.id}"]:checked`)).map(e=>e.value):[el.value];Learning.choose(current.path,q.id,selected)}
});
document.addEventListener('submit',event=>{
 if(event.target.id==='review-form'){event.preventDefault();if(!complete(current.path))return;if(!Learning.final(current.path,Learning.draft(current.path))){document.getElementById('review-error').textContent=I18N.t('Answer every question, including the kit, before submitting.');return}location.hash='#complete/'+current.path;render()}
 if(event.target.id==='organiser-form'){event.preventDefault();organiserKey=new FormData(event.target).get('key').trim();void loadResults()}
});
document.addEventListener('click',async event=>{
 const action=event.target.closest('[data-action]')?.dataset.action;
 if(action==='refresh-results')void loadResults();
 if(action==='export-results')exportResults();
 if(action==='lock-results'){organiserKey='';organiserResults=null;render()}
 if(action==='sync-results'){await Learning.connect();await Learning.flush();privacyModal()}
 if(action==='delete-results')openModal('Delete shared results?',`<p>This deletes all quiz results shared by this browser’s learner ID from this server. Your local progress and plan stay available. Sharing will switch off.</p><button class="primary" data-action="delete-results-confirm">Delete my shared quiz results</button>`);
 if(action==='delete-results-confirm'){try{await Learning.removeShared();privacyModal();document.getElementById('tracking-status').textContent=I18N.t('Your shared quiz results have been deleted.')}catch{openModal('Your data','<p>Could not delete shared results. Start the server and try again before clearing local data.</p>')}}
});
